class Solution {
public:
    int numPermsDISequence(string s) {
        long long MOD = 1000000007;
        int n = s.length();
        vector<long long> dp = {1};
        for (int i = 0; i < n; i++) {
            vector<long long> nxt(i + 2, 0);
            if (s[i] == 'I') {
                long long cur = 0;
                for (int j = 1; j <= i + 1; j++) {
                    cur = (cur + dp[j - 1]) % MOD;
                    nxt[j] = cur;
                }
            } else {
                long long cur = 0;
                for (int j = i; j >= 0; j--) {
                    cur = (cur + dp[j]) % MOD;
                    nxt[j] = cur;
                }
            }
            dp = move(nxt);
        }
        long long ans = 0;
        for (long long x : dp) ans = (ans + x) % MOD;
        return ans;
    }
};

class Solution {
    public int numPermsDISequence(String s) {
        long MOD = 1_000_000_007L;
        int n = s.length();
        long[] dp = new long[]{1};
        for (int i = 0; i < n; i++) {
            long[] nxt = new long[i + 2];
            if (s.charAt(i) == 'I') {
                long cur = 0;
                for (int j = 1; j <= i + 1; j++) {
                    cur = (cur + dp[j - 1]) % MOD;
                    nxt[j] = cur;
                }
            } else {
                long cur = 0;
                for (int j = i; j >= 0; j--) {
                    cur = (cur + dp[j]) % MOD;
                    nxt[j] = cur;
                }
            }
            dp = nxt;
        }
        long ans = 0;
        for (long x : dp) ans = (ans + x) % MOD;
        return (int) ans;
    }
}

var numPermsDISequence = function(s) {
    const MOD = 1000000007n;
    let dp = [1n];
    for (let i = 0; i < s.length; i++) {
        const nxt = new Array(i + 2).fill(0n);
        if (s[i] === 'I') {
            let cur = 0n;
            for (let j = 1; j <= i + 1; j++) {
                cur = (cur + dp[j - 1]) % MOD;
                nxt[j] = cur;
            }
        } else {
            let cur = 0n;
            for (let j = i; j >= 0; j--) {
                cur = (cur + dp[j]) % MOD;
